package ai.xzkj.recruitment.resumes;
import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class ResumeIntakeController{private final ResumeIntakeService service;public ResumeIntakeController(ResumeIntakeService s){service=s;}@GetMapping("/api/resume-intakes")public List<ResumeIntakeResponse> list(){return service.list();}@PostMapping("/api/candidate-contacts/{contactId}/resume-intakes")public ResumeIntakeResponse create(@PathVariable UUID contactId,@Valid@RequestBody ResumeIntakeCreateRequest r){return service.create(contactId,r);}@PutMapping("/api/resume-intakes/{id}/review")public ResumeIntakeResponse review(@PathVariable UUID id,@Valid@RequestBody ResumeIntakeReviewRequest r){return service.review(id,r);}}
